import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十七卦 随 泽雷随 兑上震下","description":"周易 - 第十七卦 随 泽雷随 兑上震下","frontmatter":{"title":"第十七卦 随 泽雷随 兑上震下","description":"周易 - 第十七卦 随 泽雷随 兑上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/018.md","filePath":"zh/classics/zhouyi/018.md"}'),l={name:"zh/classics/zhouyi/018.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="随" tabindex="-1">随 <a class="header-anchor" href="#随" aria-label="Permalink to “随”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元亨利贞，无咎。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>随，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时，随之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽中有雷，随；君子以向晦入宴息。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>官有渝，贞吉。出门交有功。象曰：官有渝，从正吉也。出门交有功，不失也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>系小子，失丈夫。象曰：系小子，弗兼与也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>系丈夫，失小子。随有求得，利居贞。象曰：系丈夫，志舍下也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>随有获，贞凶。有孚在道，以明，何咎。象曰：随有获，其义凶也。有孚在道，明功也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>孚于嘉，吉。象曰：孚于嘉，吉；位正中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>拘系之，乃从维之。王用亨于西山。象曰：拘系之，上穷也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
